function smartGoal(opts){
  opts=opts||{};
  var g=(opts.goal||'目标').trim()||'目标';
  var L=[];
  L.push('# SMART 目标 · '+g);
  L.push('');
  L.push('- **S 具体**：'+(opts.specific||'（要达成什么？谁参与？在哪里？）'));
  L.push('- **M 可衡量**：'+(opts.measurable||'（用什么指标衡量？目标值是多少？）'));
  L.push('- **A 可实现**：'+(opts.achievable||'（现有资源与约束下可行吗？缺什么？）'));
  L.push('- **R 相关**：'+(opts.relevant||'（为什么现在做？与什么对齐？）'));
  L.push('- **T 有时限**：'+(opts.timebound||'（截止日期？关键里程碑？）'));
  L.push('');
  L.push('## 里程碑');
  L.push('- [ ] ____ / ____');
  L.push('- [ ] ____ / ____');
  return L.join('\n');
}

var EXPORTS={smartGoal:smartGoal};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SmartGoalForgePure = EXPORTS; }
